//! Build script: the window background colours from the design tokens, then
//! Tauri's own build step (config, capabilities, Windows resources).
use std::{env, fmt::Write as _, fs, path::Path};

/// Generated by packages/ui/scripts/generate.mjs from brand/tokens/tokens.json.
const THEME_JSON: &str = "../../../packages/ui/src/tokens/theme.json";

fn main() {
    println!("cargo:rerun-if-changed={THEME_JSON}");
    // `tauri::include_image!` (src/mark.rs) decodes these at compile time
    // but does not tell Cargo; a rerun here rebuilds the crate with them.
    for colour in ["ink", "white"] {
        for size in [16, 20, 24, 32] {
            println!("cargo:rerun-if-changed=../../../brand/png/tray-{colour}-{size}.png");
        }
    }
    let json =
        fs::read_to_string(THEME_JSON).expect("packages/ui/src/tokens/theme.json is readable");
    let themes: serde_json::Value = serde_json::from_str(&json).expect("theme.json is valid JSON");

    let mut out =
        String::from("// Generated by build.rs from packages/ui/src/tokens/theme.json.\n");
    for theme in ["light", "dark"] {
        let hex = themes[theme]["content"]
            .as_str()
            .expect("theme.json has a content colour per theme");
        let [r, g, b] = parse_hex(hex);
        let name = theme.to_uppercase();
        writeln!(out, "/// The {theme} theme's content background.").expect("infallible");
        writeln!(
            out,
            "pub(crate) const {name}_CONTENT: tauri::window::Color = \
             tauri::window::Color({r}, {g}, {b}, 255);"
        )
        .expect("infallible");
    }
    let dest = Path::new(&env::var("OUT_DIR").expect("Cargo sets OUT_DIR")).join("theme.rs");
    fs::write(dest, out).expect("OUT_DIR is writable");

    tauri_build::build();
}

fn parse_hex(hex: &str) -> [u8; 3] {
    let channel =
        |i: usize| u8::from_str_radix(hex.get(i..i + 2).expect("#RRGGBB"), 16).expect("hex digits");
    [channel(1), channel(3), channel(5)]
}
